770	/**
771	 * Put noise factor
772	 * bits            Bitstream context
773	 * nf              Noise factor (0 to 7)
774	 */
775	static void put_noise_factor(lc3_bits_t *bits, int nf)
776	{
777	    lc3_put_bits(bits, nf, 3);
778	}
