780	/**
781	 * Get noise factor
782	 * bits            Bitstream context
783	 * return          Noise factor (0 to 7)
784	 */
785	static int get_noise_factor(lc3_bits_t *bits)
786	{
787	    return lc3_get_bits(bits, 3);
788	}
