201	/**
202	 * Windowing of samples before MDCT
203	 * dt, sr          Duration and samplerate
204	 * x, y            Input current and delayed samples
205	 * y, d            Output windowed samples, and delayed ones
206	 */
207	LC3_HOT static void mdct_window(
208	    enum lc3_dt dt, enum lc3_srate sr,
209	    const float *x, float *d, float *y)
210	{
211	    const float *win = lc3_mdct_win[dt][sr];
212	    int ns = lc3_ns(dt, sr), nd = lc3_nd(dt, sr);
213	
214	    const float *w0 = win, *w1 = w0 + ns;
215	    const float *w2 = w1, *w3 = w2 + nd;
216	
217	    const float *x0 = x + ns-nd, *x1 = x0;
218	    float *y0 = y + ns/2, *y1 = y0;
219	    float *d0 = d, *d1 = d + nd;
220	
221	    while (x1 > x) {
222	        *(--y0) = *d0 * *(w0++) - *(--x1) * *(--w1);
223	        *(y1++) = (*(d0++) = *(x0++)) * *(w2++);
224	
225	        *(--y0) = *d0 * *(w0++) - *(--x1) * *(--w1);
226	        *(y1++) = (*(d0++) = *(x0++)) * *(w2++);
227	    }
228	
229	    for (x1 += ns; x0 < x1; ) {
230	        *(--y0) = *d0 * *(w0++) - *(--d1) * *(--w1);
231	        *(y1++) = (*(d0++) = *(x0++)) * *(w2++) + (*d1 = *(--x1)) * *(--w3);
232	
233	        *(--y0) = *d0 * *(w0++) - *(--d1) * *(--w1);
234	        *(y1++) = (*(d0++) = *(x0++)) * *(w2++) + (*d1 = *(--x1)) * *(--w3);
235	    }
236	}
