238	/**
239	 * Pre-rotate MDCT coefficients of N/2 points, before FFT N/4 points FFT
240	 * def             Size and twiddles factors
241	 * x, y            Input and output coefficients
242	 *
243	 * `x` and y` can be the same buffer
244	 */
245	LC3_HOT static void mdct_pre_fft(const struct lc3_mdct_rot_def *def,
246	    const float *x, struct lc3_complex *y)
247	{
248	    int n4 = def->n4;
249	
250	    const float *x0 = x, *x1 = x0 + 2*n4;
251	    const struct lc3_complex *w0 = def->w, *w1 = w0 + n4;
252	    struct lc3_complex *y0 = y, *y1 = y0 + n4;
253	
254	    while (x0 < x1) {
255	        struct lc3_complex u, uw = *(w0++);
256	        u.re = - *(--x1) * uw.re + *x0 * uw.im;
257	        u.im =   *(x0++) * uw.re + *x1 * uw.im;
258	
259	        struct lc3_complex v, vw = *(--w1);
260	        v.re = - *(--x1) * vw.im + *x0 * vw.re;
261	        v.im = - *(x0++) * vw.im - *x1 * vw.re;
262	
263	        *(y0++) = u;
264	        *(--y1) = v;
265	    }
266	}
267	
268	/**
269	 * Post-rotate FFT N/4 points coefficients, resulting MDCT N points
270	 * def             Size and twiddles factors
271	 * x, y            Input and output coefficients
272	 *
273	 * `x` and y` can be the same buffer
274	 */
275	LC3_HOT static void mdct_post_fft(const struct lc3_mdct_rot_def *def,
276	    const struct lc3_complex *x, float *y)
277	{
278	    int n4 = def->n4, n8 = n4 >> 1;
279	
280	    const struct lc3_complex *w0 = def->w + n8, *w1 = w0 - 1;
281	    const struct lc3_complex *x0 = x + n8, *x1 = x0 - 1;
282	
283	    float *y0 = y + n4, *y1 = y0;
284	
285	    for ( ; y1 > y; x0++, x1--, w0++, w1--) {
286	
287	        float u0 = x0->im * w0->im + x0->re * w0->re;
288	        float u1 = x1->re * w1->im - x1->im * w1->re;
289	
290	        float v0 = x0->re * w0->im - x0->im * w0->re;
291	        float v1 = x1->im * w1->im + x1->re * w1->re;
292	
293	        *(y0++) = u0;  *(y0++) = u1;
294	        *(--y1) = v0;  *(--y1) = v1;
295	    }
296	}
