298	/**
299	 * Pre-rotate IMDCT coefficients of N points, before FFT N/4 points FFT
300	 * def             Size and twiddles factors
301	 * x, y            Input and output coefficients
302	 *
303	 * `x` and `y` can be the same buffer
304	 * The real and imaginary parts of `y` are swapped,
305	 * to operate on FFT instead of IFFT
306	 */
307	LC3_HOT static void imdct_pre_fft(const struct lc3_mdct_rot_def *def,
308	    const float *x, struct lc3_complex *y)
309	{
310	    int n4 = def->n4;
311	
312	    const float *x0 = x, *x1 = x0 + 2*n4;
313	
314	    const struct lc3_complex *w0 = def->w, *w1 = w0 + n4;
315	    struct lc3_complex *y0 = y, *y1 = y0 + n4;
316	
317	    while (x0 < x1) {
318	        float u0 = *(x0++), u1 = *(--x1);
319	        float v0 = *(x0++), v1 = *(--x1);
320	        struct lc3_complex uw = *(w0++), vw = *(--w1);
321	
322	        (y0  )->re = - u0 * uw.re - u1 * uw.im;
323	        (y0++)->im = - u1 * uw.re + u0 * uw.im;
324	
325	        (--y1)->re = - v1 * vw.re - v0 * vw.im;
326	        (  y1)->im = - v0 * vw.re + v1 * vw.im;
327	    }
328	}
329	
330	/**
331	 * Post-rotate FFT N/4 points coefficients, resulting IMDCT N points
332	 * def             Size and twiddles factors
333	 * x, y            Input and output coefficients
334	 *
335	 * `x` and y` can be the same buffer
336	 * The real and imaginary parts of `x` are swapped,
337	 * to operate on FFT instead of IFFT
338	 */
339	LC3_HOT static void imdct_post_fft(const struct lc3_mdct_rot_def *def,
340	    const struct lc3_complex *x, float *y)
341	{
342	    int n4 = def->n4;
343	
344	    const struct lc3_complex *w0 = def->w, *w1 = w0 + n4;
345	    const struct lc3_complex *x0 = x, *x1 = x0 + n4;
346	
347	    float *y0 = y, *y1 = y0 + 2*n4;
348	
349	    while (x0 < x1) {
350	        struct lc3_complex uz = *(x0++), vz = *(--x1);
351	        struct lc3_complex uw = *(w0++), vw = *(--w1);
352	
353	        *(y0++) = uz.re * uw.im - uz.im * uw.re;
354	        *(--y1) = uz.re * uw.re + uz.im * uw.im;
355	
356	        *(--y1) = vz.re * vw.im - vz.im * vw.re;
357	        *(y0++) = vz.re * vw.re + vz.im * vw.im;
358	    }
359	}
