361	/**
362	 * Apply windowing of samples
363	 * dt, sr          Duration and samplerate
364	 * x, d            Middle half of IMDCT coefficients and delayed samples
365	 * y, d            Output samples and delayed ones
366	 */
367	LC3_HOT static void imdct_window(
368	    enum lc3_dt dt, enum lc3_srate sr,
369	    const float *x, float *d, float *y)
370	{
371	    /* The full MDCT coefficients is given by symmetry :
372	     *   T[   0 ..  n/4-1] = -half[n/4-1 .. 0    ]
373	     *   T[ n/4 ..  n/2-1] =  half[0     .. n/4-1]
374	     *   T[ n/2 .. 3n/4-1] =  half[n/4   .. n/2-1]
375	     *   T[3n/4 ..    n-1] =  half[n/2-1 .. n/4  ]  */
376	
377	    const float *win = lc3_mdct_win[dt][sr];
378	    int n4 = lc3_ns(dt, sr) >> 1, nd = lc3_nd(dt, sr);
379	    const float *w2 = win, *w0 = w2 + 3*n4, *w1 = w0;
380	
381	    const float *x0 = d + nd-n4, *x1 = x0;
382	    float *y0 = y + nd-n4, *y1 = y0, *y2 = d + nd, *y3 = d;
383	
384	    while (y0 > y) {
385	        *(--y0) = *(--x0) - *(x  ) * *(w1++);
386	        *(y1++) = *(x1++) + *(x++) * *(--w0);
387	
388	        *(--y0) = *(--x0) - *(x  ) * *(w1++);
389	        *(y1++) = *(x1++) + *(x++) * *(--w0);
390	    }
391	
392	    while (y1 < y + nd) {
393	        *(y1++) = *(x1++) + *(x++) * *(--w0);
394	        *(y1++) = *(x1++) + *(x++) * *(--w0);
395	    }
396	
397	    while (y1 < y + 2*n4) {
398	        *(y1++) = *(x  ) * *(--w0);
399	        *(--y2) = *(x++) * *(w2++);
400	
401	        *(y1++) = *(x  ) * *(--w0);
402	        *(--y2) = *(x++) * *(w2++);
403	    }
404	
405	    while (y2 > y3) {
406	        *(y3++) = *(x  ) * *(--w0);
407	        *(--y2) = *(x++) * *(w2++);
408	
409	        *(y3++) = *(x  ) * *(--w0);
410	        *(--y2) = *(x++) * *(w2++);
411	    }
412	}
413	
414	/**
415	 * Rescale samples
416	 * x, n            Input and count of samples, scaled as output
417	 * scale           Scale factor
418	 */
419	LC3_HOT static void rescale(float *x, int n, float f)
420	{
421	    for (int i = 0; i < (n >> 2); i++) {
422	        *(x++) *= f; *(x++) *= f;
423	        *(x++) *= f; *(x++) *= f;
424	    }
425	}
426	
427	/**
428	 * Forward MDCT transformation
429	 */
430	void lc3_mdct_forward(
431	    enum lc3_dt dt, enum lc3_srate sr, enum lc3_srate sr_dst,
432	    const float *x, float *d, float *y)
433	{
434	    const struct lc3_mdct_rot_def *rot = lc3_mdct_rot[dt][sr];
435	    int ns_dst = lc3_ns(dt, sr_dst);
436	    int ns = lc3_ns(dt, sr);
437	
438	    struct lc3_complex buffer[LC3_MAX_NS / 2];
439	    struct lc3_complex *z = (struct lc3_complex *)y;
440	    union { float *f; struct lc3_complex *z; } u = { .z = buffer };
441	
442	    mdct_window(dt, sr, x, d, u.f);
443	
444	    mdct_pre_fft(rot, u.f, u.z);
445	    u.z = fft(u.z, ns/2, u.z, z);
446	    mdct_post_fft(rot, u.z, y);
447	
448	    if (ns != ns_dst)
449	        rescale(y, ns_dst, sqrtf((float)ns_dst / ns));
450	}
451	
452	/**
453	 * Inverse MDCT transformation
454	 */
455	void lc3_mdct_inverse(
456	    enum lc3_dt dt, enum lc3_srate sr, enum lc3_srate sr_src,
457	    const float *x, float *d, float *y)
458	{
459	    const struct lc3_mdct_rot_def *rot = lc3_mdct_rot[dt][sr];
460	    int ns_src = lc3_ns(dt, sr_src);
461	    int ns = lc3_ns(dt, sr);
462	
463	    struct lc3_complex buffer[LC3_MAX_NS / 2];
464	    struct lc3_complex *z = (struct lc3_complex *)y;
465	    union { float *f; struct lc3_complex *z; } u = { .z = buffer };
466	
467	    imdct_pre_fft(rot, x, z);
468	    z = fft(z, ns/2, z, u.z);
469	    imdct_post_fft(rot, z, u.f);
470	
471	    if (ns != ns_src)
472	        rescale(u.f, ns, sqrtf((float)ns / ns_src));
473	
474	    imdct_window(dt, sr, u.f, d, y);
475	}
