285	/**
286	 * Arithmetic coder renormalization
287	 */
288	LC3_HOT void lc3_ac_write_renorm(struct lc3_bits *bits)
289	{
290	    struct lc3_bits_ac *ac = &bits->ac;
291	
292	    for ( ; ac->range < 0x10000; ac->range <<= 8)
293	        ac_shift(ac, &bits->buffer);
294	}
