static inline int32_t saturate_32bit_to_16bit(int32_t a) {
    return (a > 32767) ? 32767 : ((a < -32768) ? -32768 : a);
}
#undef WORD2INT
#define WORD2INT(x) (saturate_32bit_to_16bit(x))

#define OVERRIDE_INNER_PRODUCT_SINGLE
static inline int32_t inner_product_single(const int16_t *a, const int16_t *b, unsigned int len)
{
    ae_int64 acc0, acc1;
    ae_int16x4 va0, va1, vb0, vb1;
    ae_valign align_a, align_b;
    const ae_int16x4 *pa;
    const ae_int16x4 *pb;
    unsigned int i;

    if (len == 0)
        return 0;

    acc0 = AE_ZERO64();
    acc1 = AE_ZERO64();
    pa = (const ae_int16x4 *)a;
    pb = (const ae_int16x4 *)b;
    align_a = AE_LA64_PP(pa);
    align_b = AE_LA64_PP(pb);

    for (i = 0; i + 8 <= len; i += 8)
    {
        AE_LA16X4_IP(va0, align_a, pa);
        AE_LA16X4_IP(va1, align_a, pa);
        AE_LA16X4_IP(vb0, align_b, pb);
        AE_LA16X4_IP(vb1, align_b, pb);
        AE_MULAAAAQ16(acc0, va0, vb0);
        AE_MULAAAAQ16(acc1, va1, vb1);
    }

    if (i + 4 <= len)
    {
        AE_LA16X4_IP(va0, align_a, pa);
        AE_LA16X4_IP(vb0, align_b, pb);
        AE_MULAAAAQ16(acc0, va0, vb0);
        i += 4;
    }

    acc0 = AE_ADD64(acc0, acc1);

    {
        int32_t tail_sum = 0;
        for (; i < len; i++)
            tail_sum += ((int32_t)a[i]) * ((int32_t)b[i]);
        acc0 = AE_ADD64(acc0, (ae_int64)tail_sum);
    }

    return SATURATE32PSHR(AE_MOVAD32_L(AE_MOVINT32X2_FROMINT64(acc0)), 15, 32767);
}

#define OVERRIDE_INTERPOLATE_PRODUCT_SINGLE
static inline int32_t interpolate_product_single(const int16_t *a,
    const int16_t *b, unsigned int len, const spx_uint32_t oversample,
    spx_word16_t *interp)
{
    ae_int32x2 acc01 = AE_ZERO32();
    ae_int32x2 acc23 = AE_ZERO32();
    ae_int16x4 va, vb;
    ae_valign align_b;
    spx_word32_t sum;
    unsigned int j;

    for (j = 0; j < len; j++) {
        int16_t aj = a[j];
        va = AE_MOVDA16(aj);

        const ae_int16x4 *pb = (const ae_int16x4 *)&b[j * oversample];
        align_b = AE_LA64_PP(pb);
        AE_LA16X4_IP(vb, align_b, pb);

        AE_MULA16X4(acc01, acc23, va, vb);
    }

    {
        int32_t a0 = AE_MOVAD32_H(acc01);
        int32_t a1 = AE_MOVAD32_L(acc01);
        int32_t a2 = AE_MOVAD32_H(acc23);
        int32_t a3 = AE_MOVAD32_L(acc23);

        sum = MULT16_32_Q15(interp[0], a0)
            + MULT16_32_Q15(interp[1], a1)
            + MULT16_32_Q15(interp[2], a2)
            + MULT16_32_Q15(interp[3], a3);
    }
    return SATURATE32PSHR(sum, 15, 32767);
}

#endif /* FIXED_POINT */

#endif /* RESAMPLE_HIFI_H */

