static int ff_resample_common_float_hifi4(ResampleContext *c, void *dest, const void *source,
                                         int n, int update_ctx)
{
    float *dst = dest;
    const float *src = source;
    float *filter, val;
    int dst_index, i;
    int index = c->index;
    int frac = c->frac;
    int sample_index = 0;
    int dsp_len = c->filter_length >= 4 ? c->filter_length & ~3 : 0;

    while (index >= c->phase_count) {
        sample_index++;
        index -= c->phase_count;
    }

    for (dst_index = 0; dst_index < n; dst_index++) {
        filter = ((float *)c->filter_bank) + c->filter_alloc * index;
        val = 0;
        i = 0;

        if (dsp_len >= 4) {
            const ae_int32x2 *pisrc = (const ae_int32x2 *)&src[sample_index];
            const xtfloatx2 *pfilter = (const xtfloatx2 *)filter;
            ae_valign va_src = AE_LA64_PP(pisrc);
            xtfloatx2 acc0 = XT_CONST_S(0);
            xtfloatx2 acc1 = XT_CONST_S(0);

            for (int t = dsp_len; t > 0; t -= 4) {
                ae_int32x2 is0, is1;
                xtfloatx2 src0, src1, filter0, filter1;
                AE_LA32X2_IP(is0, va_src, pisrc);
                AE_LA32X2_IP(is1, va_src, pisrc);
                src0 = AE_MOVXTFLOATX2_FROMINT32X2(is0);
                src1 = AE_MOVXTFLOATX2_FROMINT32X2(is1);
                XT_LSX2IP(filter0, pfilter, sizeof(xtfloatx2));
                XT_LSX2IP(filter1, pfilter, sizeof(xtfloatx2));
                XT_MADD_SX2(acc0, src0, filter0);
                XT_MADD_SX2(acc1, src1, filter1);
            }
            xtfloatx2 acc = XT_ADD_SX2(acc0, acc1);
            val += XT_ADD_S(XT_HIGH_S(acc), XT_LOW_S(acc));
            i = dsp_len;
        }

        for (; i < c->filter_length; i++) {
            val += src[sample_index + i] * filter[i];
        }

        dst[dst_index] = val;

        frac  += c->dst_incr_mod;
        index += c->dst_incr_div;
        if (frac >= c->src_incr) {
            frac -= c->src_incr;
            index++;
        }

        while (index >= c->phase_count) {
            sample_index++;
            index -= c->phase_count;
        }
    }

    if (update_ctx) {
        c->frac = frac;
        c->index = index;
    }

    return sample_index;
}

static int ff_resample_common_s16_hifi4(ResampleContext *c, void *dest, const void *source,
                                       int n, int update_ctx)
{
    const int16_t *src = source;
    int16_t *dst = dest;
    int16_t *filter;
    int sample_index = 0;
    int index = c->index;
    int frac = c->frac;
    int dst_index, i;
    int32_t dsp_len = c->filter_length >= 8 ? c->filter_length & ~7 : c->filter_length >= 4 ? c->filter_length & ~3 : 0;
    int32_t val;

    while (index >= c->phase_count) {
        sample_index++;
        index -= c->phase_count;
    }

    for (dst_index = 0; dst_index < n; dst_index++) {
        filter = ((int16_t *)c->filter_bank) + c->filter_alloc * index;
        val = 0;
        i = 0;

        if (dsp_len >= 4) {
            const ae_int16x4 *psrc = (const ae_int16x4 *)&src[sample_index];
            const ae_int16x4 *pflt = (const ae_int16x4 *)filter;
            ae_valign va_src = AE_LA64_PP(psrc);
            ae_int32x2 acc0 = AE_MOVI(0);
            ae_int32x2 acc1 = AE_MOVI(0);

            if (dsp_len >= 8) {
                ae_int16x4 src0, src1, filter0, filter1;
                for (int t = dsp_len; t > 0; t -= 8) {
                    AE_LA16X4_IP(src0, va_src, psrc);
                    AE_LA16X4_IP(src1, va_src, psrc);
                    AE_L16X4_IP(filter0, pflt, 8);
                    AE_L16X4_IP(filter1, pflt, 8);
                    AE_MULA16X4(acc0, acc1, src0, filter0);
                    AE_MULA16X4(acc0, acc1, src1, filter1);
                }
            } else {
                ae_int16x4 src0, filter0;
                for (int t = dsp_len; t > 0; t -= 4) {
                    AE_LA16X4_IP(src0, va_src, psrc);
                    AE_L16X4_IP(filter0, pflt, 8);
                    AE_MULA16X4(acc0, acc1, src0, filter0);
                }
            }
            ae_int32x2 sum0 = AE_ADD32(acc0, acc1);
            ae_int32x2 sum1 = AE_ADD32_HL_LH(sum0, sum0);
            val += AE_MOVAD32_L(sum1);
            i = dsp_len;
        }

        for (; i < c->filter_length; i++) {
            val += src[sample_index + i] * filter[i];
        }

        val = (val + (1 << 14)) >> 15;
        dst[dst_index] = av_clip_int16(val);

        frac  += c->dst_incr_mod;
        index += c->dst_incr_div;
        if (frac >= c->src_incr) {
            frac -= c->src_incr;
            index++;
        }

        while (index >= c->phase_count) {
            sample_index++;
            index -= c->phase_count;
        }
    }

    if (update_ctx) {
        c->frac = frac;
        c->index = index;
    }

    return sample_index;
}

static int ff_resample_common_s32_hifi4(ResampleContext *c, void *dest, const void *source,
                                        int n, int update_ctx)
{
    const int32_t *src = source;
    int32_t *dst = dest;
    int32_t *filter;
    int sample_index = 0;
    int index = c->index;
    int frac = c->frac;
    int dst_index, i;
    int32_t dsp_len = c->filter_length >= 4 ? c->filter_length & ~3 : 0;

    while (index >= c->phase_count) {
        sample_index++;
        index -= c->phase_count;
    }

    for (dst_index = 0; dst_index < n; dst_index++) {
        filter = ((int32_t *)c->filter_bank) + c->filter_alloc * index;
        int64_t val = 0;
        i = 0;

        if (dsp_len >= 4) {
            const ae_int32x2 *psrc = (const ae_int32x2 *)&src[sample_index];
            const ae_int32x2 *pflt = (const ae_int32x2 *)filter;
            ae_valign va_src = AE_LA64_PP(psrc);
            ae_int64 acc = AE_ZERO64();

            for (int t = dsp_len; t > 0; t -= 4) {
                ae_int32x2 s0, s1, f0, f1;
                AE_LA32X2_IP(s0, va_src, psrc);
                AE_LA32X2_IP(s1, va_src, psrc);
                AE_L32X2_IP(f0, pflt, 8);
                AE_L32X2_IP(f1, pflt, 8);
                AE_MULAAFD32S_HH_LL(acc, s0, f0);
                AE_MULAAFD32S_HH_LL(acc, s1, f1);
            }
            val = *(int64_t *)&acc;
            /* AE_MULAAFD32S_HH_LL is fractional (result << 1), compensate */
            val >>= 1;
            i = dsp_len;
        }

        for (; i < c->filter_length; i++)
            val += (int64_t)src[sample_index + i] * filter[i];

        dst[dst_index] = av_clipl_int32((val + (1 << 29)) >> 30);

        frac  += c->dst_incr_mod;
        index += c->dst_incr_div;
        if (frac >= c->src_incr) {
            frac -= c->src_incr;
            index++;
        }

        while (index >= c->phase_count) {
            sample_index++;
            index -= c->phase_count;
        }
    }

    if (update_ctx) {
        c->frac = frac;
        c->index = index;
    }

    return sample_index;
}

av_cold void swri_resample_dsp_hifi4_init(ResampleContext *c)
{
    switch(c->format) {
    case AV_SAMPLE_FMT_FLTP:
        c->dsp.resample_common = ff_resample_common_float_hifi4;
        break;
    case AV_SAMPLE_FMT_S16P:
        c->dsp.resample_common = ff_resample_common_s16_hifi4;
        break;
    case AV_SAMPLE_FMT_S32P:
        c->dsp.resample_common = ff_resample_common_s32_hifi4;
        break;
    }
}

