142	/**
143	 * Resolve the bitrate, from the size of frames or frame blocks
144	 */
145	LC3_EXPORT int lc3_hr_resolve_bitrate(
146	    bool hrmode, int dt_us, int sr_hz, int nbytes)
147	{
148	    enum lc3_dt dt = resolve_dt(dt_us, hrmode);
149	    enum lc3_srate sr = resolve_srate(sr_hz, hrmode);
150	
151	    if (dt >= LC3_NUM_DT || sr >= LC3_NUM_SRATE || nbytes < 0)
152	        return -1;
153	
154	    return LC3_MIN(((int64_t)nbytes * 3200 + dt) / (1 + dt), INT_MAX);
155	}
156	
157	LC3_EXPORT int lc3_resolve_bitrate(int dt_us, int nbytes)
158	{
159	    return lc3_hr_resolve_bitrate(false, dt_us, 8000, nbytes);
160	}
