162	/**
163	 * Return algorithmic delay, as a number of samples
164	 */
165	LC3_EXPORT int lc3_hr_delay_samples(bool hrmode, int dt_us, int sr_hz)
166	{
167	    enum lc3_dt dt = resolve_dt(dt_us, hrmode);
168	    enum lc3_srate sr = resolve_srate(sr_hz, hrmode);
169	
170	    if (dt >= LC3_NUM_DT || sr >= LC3_NUM_SRATE)
171	        return -1;
172	
173	    return 2 * lc3_nd(dt, sr) - lc3_ns(dt, sr);
174	}
