186	/**
187	 * Input PCM Samples from signed 16 bits
188	 * encoder         Encoder state
189	 * pcm, stride     Input PCM samples, and count between two consecutives
190	 */
191	static void load_s16(
192	    struct lc3_encoder *encoder, const void *_pcm, int stride)
193	{
194	    const int16_t *pcm = _pcm;
195	
196	    enum lc3_dt dt = encoder->dt;
197	    enum lc3_srate sr = encoder->sr_pcm;
198	
199	    int16_t *xt = (int16_t *)encoder->x + encoder->xt_off;
200	    float *xs = encoder->x + encoder->xs_off;
201	    int ns = lc3_ns(dt, sr);
202	
203	    for (int i = 0; i < ns; i++, pcm += stride)
204	        xt[i] = *pcm, xs[i] = *pcm;
205	}
206	
207	/**
208	 * Input PCM Samples from signed 24 bits
209	 * encoder         Encoder state
210	 * pcm, stride     Input PCM samples, and count between two consecutives
211	 */
212	static void load_s24(
213	    struct lc3_encoder *encoder, const void *_pcm, int stride)
214	{
215	    const int32_t *pcm = _pcm;
216	
217	    enum lc3_dt dt = encoder->dt;
218	    enum lc3_srate sr = encoder->sr_pcm;
219	
220	    int16_t *xt = (int16_t *)encoder->x + encoder->xt_off;
221	    float *xs = encoder->x + encoder->xs_off;
222	    int ns = lc3_ns(dt, sr);
223	
224	    for (int i = 0; i < ns; i++, pcm += stride) {
225	        xt[i] = *pcm >> 8;
226	        xs[i] = lc3_ldexpf(*pcm, -8);
227	    }
228	}
229	
230	/**
231	 * Input PCM Samples from signed 24 bits packed
232	 * encoder         Encoder state
233	 * pcm, stride     Input PCM samples, and count between two consecutives
234	 */
235	static void load_s24_3le(
236	    struct lc3_encoder *encoder, const void *_pcm, int stride)
237	{
238	    const uint8_t *pcm = _pcm;
239	
240	    enum lc3_dt dt = encoder->dt;
241	    enum lc3_srate sr = encoder->sr_pcm;
242	
243	    int16_t *xt = (int16_t *)encoder->x + encoder->xt_off;
244	    float *xs = encoder->x + encoder->xs_off;
245	    int ns = lc3_ns(dt, sr);
246	
247	    for (int i = 0; i < ns; i++, pcm += 3*stride) {
248	        int32_t in = ((uint32_t)pcm[0] <<  8) |
249	                     ((uint32_t)pcm[1] << 16) |
250	                     ((uint32_t)pcm[2] << 24)  ;
251	
252	        xt[i] = in >> 16;
253	        xs[i] = lc3_ldexpf(in, -16);
254	    }
255	}
256	
257	/**
258	 * Input PCM Samples from float 32 bits
259	 * encoder         Encoder state
260	 * pcm, stride     Input PCM samples, and count between two consecutives
261	 */
262	static void load_float(
263	    struct lc3_encoder *encoder, const void *_pcm, int stride)
264	{
265	    const float *pcm = _pcm;
266	
267	    enum lc3_dt dt = encoder->dt;
268	    enum lc3_srate sr = encoder->sr_pcm;
269	
270	    int16_t *xt = (int16_t *)encoder->x + encoder->xt_off;
271	    float *xs = encoder->x + encoder->xs_off;
272	    int ns = lc3_ns(dt, sr);
273	
274	    for (int i = 0; i < ns; i++, pcm += stride) {
275	        xs[i] = lc3_ldexpf(*pcm, 15);
276	        xt[i] = LC3_SAT16((int32_t)xs[i]);
277	    }
278	}
279	
280	/**
281	 * Frame Analysis
282	 * encoder         Encoder state
283	 * nbytes          Size in bytes of the frame
284	 * side            Return frame data
285	 */
286	static void analyze(struct lc3_encoder *encoder,
287	    int nbytes, struct side_data *side)
288	{
289	    enum lc3_dt dt = encoder->dt;
290	    enum lc3_srate sr = encoder->sr;
291	    enum lc3_srate sr_pcm = encoder->sr_pcm;
292	
293	    int16_t *xt = (int16_t *)encoder->x + encoder->xt_off;
294	    float *xs = encoder->x + encoder->xs_off;
295	    int ns = lc3_ns(dt, sr_pcm);
296	    int nt = lc3_nt(sr_pcm);
297	
298	    float *xd = encoder->x + encoder->xd_off;
299	    float *xf = xs;
300	    LC3_PROFILE_DECLARE(analyze_start);
301	    LC3_PROFILE_DECLARE(stage_start);
302	
303	    LC3_PROFILE_BEGIN(&encoder->profile, analyze_start);
304	
305	    /* --- Temporal --- */
306	
307	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
308	    bool att = lc3_attdet_run(dt, sr_pcm, nbytes, &encoder->attdet, xt);
309	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_ATTDET, stage_start);
310	
311	    if (encoder->ltpf_bypass) {
312	        side->pitch_present = false;
313	    } else {
314	        LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
315	        side->pitch_present = lc3_ltpf_analyse(
316	            dt, sr_pcm, &encoder->ltpf, xt, &side->ltpf);
317	        LC3_PROFILE_END(&encoder->profile,
318	            LC3_PROFILE_LTPF_TOTAL, stage_start);
319	    }
320	
321	    memmove(xt - nt, xt + (ns-nt), nt * sizeof(*xt));
322	
323	    /* --- Spectral --- */
324	
325	    float e[LC3_MAX_BANDS];
326	
327	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
328	    lc3_mdct_forward(dt, sr_pcm, sr, xs, xd, xf);
329	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_MDCT, stage_start);
330	
331	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
332	    bool nn_flag = lc3_energy_compute(dt, sr, xf, e);
333	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_ENERGY, stage_start);
334	    if (nn_flag || encoder->ltpf_bypass)
335	        lc3_ltpf_disable(&side->ltpf);
336	
337	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
338	    side->bw = lc3_bwdet_run(dt, sr, e);
339	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_BWDET, stage_start);
340	
341	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
342	    lc3_sns_analyze(dt, sr, nbytes, e, att, &side->sns, xf, xf
343	        LC3_PROFILE_ARG(&encoder->profile));
344	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_SNS, stage_start);
345	
346	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
347	    lc3_tns_analyze(dt, side->bw, nn_flag, nbytes, &side->tns, xf);
348	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_TNS, stage_start);
349	
350	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
351	    lc3_spec_analyze(dt, sr,
352	        nbytes, side->pitch_present, &side->tns,
353	        &encoder->spec, xf, &side->spec);
354	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_SPEC_ANALYZE, stage_start);
355	
356	    LC3_PROFILE_END(&encoder->profile,
357	        LC3_PROFILE_ANALYZE_TOTAL, analyze_start);
358	}
359	
360	/**
361	 * Encode bitstream
362	 * encoder         Encoder state
363	 * side            The frame data
364	 * nbytes          Target size of the frame (20 to 400)
365	 * buffer          Output bitstream buffer of `nbytes` size
366	 */
367	static void encode(struct lc3_encoder *encoder,
368	    const struct side_data *side, int nbytes, void *buffer)
369	{
370	    enum lc3_dt dt = encoder->dt;
371	    enum lc3_srate sr = encoder->sr;
372	
373	    float *xf = encoder->x + encoder->xs_off;
374	    enum lc3_bandwidth bw = side->bw;
375	
376	    lc3_bits_t bits;
377	
378	    lc3_setup_bits(&bits, LC3_BITS_MODE_WRITE, buffer, nbytes);
379	
380	    lc3_bwdet_put_bw(&bits, sr, bw);
381	
382	    lc3_spec_put_side(&bits, dt, sr, &side->spec);
383	
384	    lc3_tns_put_data(&bits, &side->tns);
385	
386	    lc3_put_bit(&bits, side->pitch_present);
387	
388	    lc3_sns_put_data(&bits, &side->sns);
389	
390	    if (side->pitch_present)
391	        lc3_ltpf_put_data(&bits, &side->ltpf);
392	
393	    lc3_spec_encode(&bits, dt, sr, bw, nbytes, &side->spec, xf);
394	
395	    lc3_flush_bits(&bits);
396	}
