416	/**
417	 * Setup encoder
418	 */
419	LC3_EXPORT struct lc3_encoder *lc3_hr_setup_encoder(
420	    bool hrmode, int dt_us, int sr_hz, int sr_pcm_hz, void *mem)
421	{
422	    if (sr_pcm_hz <= 0)
423	        sr_pcm_hz = sr_hz;
424	
425	    enum lc3_dt dt = resolve_dt(dt_us, hrmode);
426	    enum lc3_srate sr = resolve_srate(sr_hz, hrmode);
427	    enum lc3_srate sr_pcm = resolve_srate(sr_pcm_hz, hrmode);
428	
429	    if (dt >= LC3_NUM_DT || sr_pcm >= LC3_NUM_SRATE || sr > sr_pcm || !mem)
430	        return NULL;
431	
432	    struct lc3_encoder *encoder = mem;
433	    int ns = lc3_ns(dt, sr_pcm);
434	    int nt = lc3_nt(sr_pcm);
435	
436	    *encoder = (struct lc3_encoder){
437	        .dt = dt, .sr = sr,
438	        .sr_pcm = sr_pcm,
439	
440	        .xt_off = nt,
441	        .xs_off = (nt + ns) / 2,
442	        .xd_off = (nt + ns) / 2 + ns,
443	    };
444	
445	    LC3_PROFILE_INIT(&encoder->profile);
446	    LC3_PROFILE_BIND_LTPF(&encoder->ltpf, &encoder->profile);
447	
448	    memset(encoder->x, 0,
449	        LC3_ENCODER_BUFFER_COUNT(dt_us, sr_pcm_hz) * sizeof(float));
450	
451	    return encoder;
452	}
