454	LC3_EXPORT struct lc3_encoder *lc3_setup_encoder(
455	    int dt_us, int sr_hz, int sr_pcm_hz, void *mem)
456	{
457	    return lc3_hr_setup_encoder(false, dt_us, sr_hz, sr_pcm_hz, mem);
458	}
