475	/**
476	 * Encode a frame
477	 */
478	LC3_EXPORT int lc3_encode(struct lc3_encoder *encoder,
479	    enum lc3_pcm_format fmt, const void *pcm, int stride, int nbytes, void *out)
480	{
481	    static void (* const load[])(struct lc3_encoder *, const void *, int) = {
482	        [LC3_PCM_FORMAT_S16    ] = load_s16,
483	        [LC3_PCM_FORMAT_S24    ] = load_s24,
484	        [LC3_PCM_FORMAT_S24_3LE] = load_s24_3le,
485	        [LC3_PCM_FORMAT_FLOAT  ] = load_float,
486	    };
487	    LC3_PROFILE_DECLARE(encode_start);
488	    LC3_PROFILE_DECLARE(stage_start);
489	
490	    /* --- Check parameters --- */
491	
492	    if (!encoder || nbytes < lc3_min_frame_bytes(encoder->dt, encoder->sr)
493	                 || nbytes > lc3_max_frame_bytes(encoder->dt, encoder->sr))
494	        return -1;
495	
496	    /* --- Processing --- */
497	
498	    struct side_data side;
499	
500	    LC3_PROFILE_FRAME_BEGIN(&encoder->profile,
501	        encoder->dt, encoder->sr_pcm, nbytes);
502	    LC3_PROFILE_BEGIN(&encoder->profile, encode_start);
503	
504	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
505	    load[fmt](encoder, pcm, stride);
506	    LC3_PROFILE_END(&encoder->profile, LC3_PROFILE_LOAD_PCM, stage_start);
507	
508	    analyze(encoder, nbytes, &side);
509	
510	    LC3_PROFILE_BEGIN(&encoder->profile, stage_start);
511	    encode(encoder, &side, nbytes, out);
512	    LC3_PROFILE_END(&encoder->profile,
513	        LC3_PROFILE_BITSTREAM_ENCODE, stage_start);
514	
515	    LC3_PROFILE_END(&encoder->profile,
516	        LC3_PROFILE_ENCODE_TOTAL, encode_start);
517	    LC3_PROFILE_FRAME_END(&encoder->profile);
518	
519	    return 0;
520	}
