523	/* ----------------------------------------------------------------------------
524	 *  Decoder
525	 * -------------------------------------------------------------------------- */
526	
527	/**
528	 * Output PCM Samples to signed 16 bits
529	 * decoder         Decoder state
530	 * pcm, stride     Output PCM samples, and count between two consecutives
531	 */
532	static void store_s16(
533	    struct lc3_decoder *decoder, void *_pcm, int stride)
534	{
535	    int16_t *pcm = _pcm;
536	
537	    enum lc3_dt dt = decoder->dt;
538	    enum lc3_srate sr = decoder->sr_pcm;
539	
540	    float *xs = decoder->x + decoder->xs_off;
541	    int ns = lc3_ns(dt, sr);
542	
543	    for ( ; ns > 0; ns--, xs++, pcm += stride) {
544	        int32_t s = *xs >= 0 ? (int)(*xs + 0.5f) : (int)(*xs - 0.5f);
545	        *pcm = LC3_SAT16(s);
546	    }
547	}
548	
549	/**
550	 * Output PCM Samples to signed 24 bits
551	 * decoder         Decoder state
552	 * pcm, stride     Output PCM samples, and count between two consecutives
553	 */
554	static void store_s24(
555	    struct lc3_decoder *decoder, void *_pcm, int stride)
556	{
557	    int32_t *pcm = _pcm;
558	
559	    enum lc3_dt dt = decoder->dt;
560	    enum lc3_srate sr = decoder->sr_pcm;
561	
562	    float *xs = decoder->x + decoder->xs_off;
563	    int ns = lc3_ns(dt, sr);
564	
565	    for ( ; ns > 0; ns--, xs++, pcm += stride) {
566	        int32_t s = *xs >= 0 ? (int32_t)(lc3_ldexpf(*xs, 8) + 0.5f)
567	                             : (int32_t)(lc3_ldexpf(*xs, 8) - 0.5f);
568	        *pcm = LC3_SAT24(s);
569	    }
570	}
571	
572	/**
573	 * Output PCM Samples to signed 24 bits packed
574	 * decoder         Decoder state
575	 * pcm, stride     Output PCM samples, and count between two consecutives
576	 */
577	static void store_s24_3le(
578	    struct lc3_decoder *decoder, void *_pcm, int stride)
579	{
580	    uint8_t *pcm = _pcm;
581	
582	    enum lc3_dt dt = decoder->dt;
583	    enum lc3_srate sr = decoder->sr_pcm;
584	
585	    float *xs = decoder->x + decoder->xs_off;
586	    int ns = lc3_ns(dt, sr);
587	
588	    for ( ; ns > 0; ns--, xs++, pcm += 3*stride) {
589	        int32_t s = *xs >= 0 ? (int32_t)(lc3_ldexpf(*xs, 8) + 0.5f)
590	                             : (int32_t)(lc3_ldexpf(*xs, 8) - 0.5f);
591	
592	        s = LC3_SAT24(s);
593	        pcm[0] = (s >>  0) & 0xff;
594	        pcm[1] = (s >>  8) & 0xff;
595	        pcm[2] = (s >> 16) & 0xff;
596	    }
597	}
598	
599	/**
600	 * Output PCM Samples to float 32 bits
601	 * decoder         Decoder state
602	 * pcm, stride     Output PCM samples, and count between two consecutives
603	 */
604	static void store_float(
605	    struct lc3_decoder *decoder, void *_pcm, int stride)
606	{
607	    float *pcm = _pcm;
608	
609	    enum lc3_dt dt = decoder->dt;
610	    enum lc3_srate sr = decoder->sr_pcm;
611	
612	    float *xs = decoder->x + decoder->xs_off;
613	    int ns = lc3_ns(dt, sr);
614	
615	    for ( ; ns > 0; ns--, xs++, pcm += stride) {
616	        float s = lc3_ldexpf(*xs, -15);
617	        *pcm = fminf(fmaxf(s, -1.f), 1.f);
618	    }
619	}
620	
621	/**
622	 * Decode bitstream
623	 * decoder         Decoder state
624	 * data, nbytes    Input bitstream buffer
625	 * side            Return the side data
626	 * return          0: Ok  < 0: Bitsream error detected
627	 */
628	static int decode(struct lc3_decoder *decoder,
629	    const void *data, int nbytes, struct side_data *side)
630	{
631	    enum lc3_dt dt = decoder->dt;
632	    enum lc3_srate sr = decoder->sr;
633	
634	    float *xf = decoder->x + decoder->xs_off;
635	    int ns = lc3_ns(dt, sr);
636	    int ne = lc3_ne(dt, sr);
637	
638	    lc3_bits_t bits;
639	    int ret = 0;
640	
641	    lc3_setup_bits(&bits, LC3_BITS_MODE_READ, (void *)data, nbytes);
642	
643	    if ((ret = lc3_bwdet_get_bw(&bits, sr, &side->bw)) < 0)
644	        return ret;
645	
646	    if ((ret = lc3_spec_get_side(&bits, dt, sr, &side->spec)) < 0)
647	        return ret;
648	
649	    if ((ret = lc3_tns_get_data(&bits, dt, side->bw, nbytes, &side->tns)) < 0)
650	        return ret;
651	
652	    side->pitch_present = lc3_get_bit(&bits);
653	
654	    if ((ret = lc3_sns_get_data(&bits, &side->sns)) < 0)
655	        return ret;
656	
657	    if (side->pitch_present)
658	      lc3_ltpf_get_data(&bits, &side->ltpf);
659	
660	    if ((ret = lc3_spec_decode(&bits, dt, sr,
661	                    side->bw, nbytes, &side->spec, xf)) < 0)
662	        return ret;
663	
664	    memset(xf + ne, 0, (ns - ne) * sizeof(float));
665	
666	    return lc3_check_bits(&bits);
667	}
668	
669	/**
670	 * Frame synthesis
671	 * decoder         Decoder state
672	 * side            Frame data, NULL performs PLC
673	 * nbytes          Size in bytes of the frame
674	 */
675	static void synthesize(struct lc3_decoder *decoder,
676	    const struct side_data *side, int nbytes)
677	{
678	    enum lc3_dt dt = decoder->dt;
679	    enum lc3_srate sr = decoder->sr;
680	    enum lc3_srate sr_pcm = decoder->sr_pcm;
681	
682	    float *xf = decoder->x + decoder->xs_off;
683	    int ns = lc3_ns(dt, sr_pcm);
684	    int ne = lc3_ne(dt, sr);
685	
686	    float *xg = decoder->x + decoder->xg_off;
687	    float *xs = xf;
688	
689	    float *xd = decoder->x + decoder->xd_off;
690	    float *xh = decoder->x + decoder->xh_off;
691	
692	    if (side) {
693	        enum lc3_bandwidth bw = side->bw;
694	
695	        lc3_plc_suspend(&decoder->plc);
696	
697	        lc3_tns_synthesize(dt, bw, &side->tns, xf);
698	
699	        lc3_sns_synthesize(dt, sr, &side->sns, xf, xg);
700	
701	        lc3_mdct_inverse(dt, sr_pcm, sr, xg, xd, xs);
702	
703	    } else {
704	        lc3_plc_synthesize(dt, sr, &decoder->plc, xg, xf);
705	
706	        memset(xf + ne, 0, (ns - ne) * sizeof(float));
707	
708	        lc3_mdct_inverse(dt, sr_pcm, sr, xf, xd, xs);
709	    }
710	
711	    if (!lc3_hr(sr))
712	        lc3_ltpf_synthesize(dt, sr_pcm, nbytes, &decoder->ltpf,
713	            side && side->pitch_present ? &side->ltpf : NULL, xh, xs);
714	}
715	
716	/**
717	 * Update decoder state on decoding completion
718	 * decoder         Decoder state
719	 */
720	static void complete(struct lc3_decoder *decoder)
721	{
722	    enum lc3_dt dt = decoder->dt;
723	    enum lc3_srate sr_pcm = decoder->sr_pcm;
724	    int nh = lc3_nh(dt, sr_pcm);
725	    int ns = lc3_ns(dt, sr_pcm);
726	
727	    decoder->xs_off = decoder->xs_off - decoder->xh_off < nh ?
728	        decoder->xs_off + ns : decoder->xh_off;
729	}
