/**
 * Fast reciprocal square root 1/sqrtf(x) approximation
 * x               Operand, positive finite number
 * return          1/sqrtf(x) approximation (max relative error ~ 0.0003%)
 *
 * Uses the classic bit-level initial guess (magic constant 0x5f3759df)
 * followed by one Newton-Raphson refinement iteration. On HiFi4 this
 * replaces a libm sqrtf call + a __divsf3 software divide (~60-100 cyc)
 * with ~5 integer/FP scalar ops. Xtensa is little-endian, so the
 * float/uint32 union aliasing is safe.
 *
 * Two Newton steps would push max relative error below 1e-7, but the
 * downstream consumers (LTPF normalized-correlation thresholds 0.6/0.85,
 * SNS pulse normalization pre-quantization) tolerate the ~3.5e-5 error
 * of one step, so a single refinement is used for the best speed/accuracy
 * trade-off.
 */
static inline float lc3_rsqrtf(float _x)
{
    union { float f; uint32_t u; } x = { .f = _x };

    /* Handle zero / negative: return 0 (callers guard the result anyway) */
    if ((x.u & 0x7fffffff) == 0 || (x.u >> 31))
        return 0;

    /* --- Initial guess via the bit-level magic constant --- */
    x.u = 0x5f3759df - (x.u >> 1);

    /* --- One Newton-Raphson iteration for 1/sqrtf(x) ---
     *   y_{n+1} = y_n * (1.5 - 0.5 * x * y_n^2) */
    float y = x.f;
    float xhalf = 0.5f * _x;
    y = y * (1.5f - xhalf * y * y);

    return y;
}


