243	    enum lc3_profile_metric metric, clock_t start)
244	{
245	    uint32_t delta;
246	
247	    if (!profile->active || metric < 0 || metric >= LC3_PROFILE_METRIC_COUNT)
248	        return;
249	
250	    delta = elapsed_cycles(start);
251	    delta = delta > profile->overhead ? delta - profile->overhead : 0;
252	
253	    if (UINT32_MAX - profile->current[metric] < delta)
254	        profile->current[metric] = UINT32_MAX;
255	    else
256	        profile->current[metric] += delta;
