285	        row = sample_row(metric);
286	        if (row >= 0 && stats->count <= LC3_PROFILE_WINDOW_FRAMES)
287	            profile->samples[row][stats->count - 1] = value;
288	    }
289	
290	    profile->frame_count++;
291	    profile->active = false;
